const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Alsek Lake polygon (approximate coordinates)
  var alsekLake = ee.Geometry.Polygon([[
    [-137.55, 60.25],
    [-137.40, 60.25],
    [-137.40, 60.35],
    [-137.55, 60.35],
    [-137.55, 60.25]
  ]]);

  // 2. Load JRC Yearly Water Classification dataset
  var jrc = ee.ImageCollection('JRC/GSW1_3/YearlyHistory');

  // 3. Get images for 1984 and 2010
  var img1984 = jrc.filter(ee.Filter.calendarRange(1984, 1984, 'year')).first();
  var img2010 = jrc.filter(ee.Filter.calendarRange(2010, 2010, 'year')).first();

  // 4. Check if images exist
  var count1984 = img1984 ? 1 : 0;
  var count2010 = img2010 ? 1 : 0;

  if (count1984 === 0 || count2010 === 0) {
    print("1984 Images: " + count1984);
    print("2010 Images: " + count2010);
    print("<answer>C1</answer>");
    return;
  }

  // 5. Create water masks (waterClass values 1,2,3 indicate water)
  var water1984 = img1984.select('waterClass').gte(1).and(img1984.select('waterClass').lte(3));
  var water2010 = img2010.select('waterClass').gte(1).and(img2010.select('waterClass').lte(3));

  // 6. Count water pixels
  var stats1984 = water1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: alsekLake,
    scale: 100,
    maxPixels: 1e9
  });
  var stats2010 = water2010.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: alsekLake,
    scale: 100,
    maxPixels: 1e9
  });

  var waterPixels1984 = stats1984.get('waterClass').getInfo();
  var waterPixels2010 = stats2010.get('waterClass').getInfo();

  // 7. Check for valid pixels
  if (waterPixels1984 === null || waterPixels2010 === null) {
    print("1984 water pixels: " + waterPixels1984);
    print("2010 water pixels: " + waterPixels2010);
    print("<answer>C2</answer>");
    return;
  }

  // 8. Validate calculations
  if (waterPixels1984 === undefined || waterPixels2010 === undefined ||
      isNaN(waterPixels1984) || isNaN(waterPixels2010) ||
      waterPixels1984 < 0 || waterPixels2010 < 0) {
    print("1984 water pixels: " + waterPixels1984);
    print("2010 water pixels: " + waterPixels2010);
    print("<answer>C3</answer>");
    return;
  }

  // 9. Print results and determine answer
  print("1984 water pixels: " + waterPixels1984);
  print("2010 water pixels: " + waterPixels2010);

  if (waterPixels2010 < waterPixels1984) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
